// === Tab: mySketch ===
/**
 * PENDULE PRO - VERSION FINALE STABILISÉE
 * Contrainte : 90° Max (Demi-sphère inférieure uniquement)
 * Grains : Taille réduite (box 3)
 */

let p_origin, p_pos, p_oldPos;
let p_len = 850; 
const G_ENV = 0.981; 
const FRICT = 0.995; 
let isDraggingTube = false;
let p_zoom = 0.6;

let particles = [];
const p_floorY = 300; 
const P_LIMIT = 50000;
const P_GAP = 10; 

function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL);

  // L'origine est placée de façon à ce que le pendule frôle le sol au repos
  p_origin = createVector(0, p_floorY - p_len - P_GAP, 0); 
  p_pos = createVector(0, p_floorY - P_GAP, 0);
  p_oldPos = p_pos.copy();

  setAttributes('antialias', true);
}

function draw() {
  background(8); 

  // --- ÉCLAIRAGE TAMISÉ ---
  ambientLight(25);
  pointLight(180, 200, 255, -2500, -1500, 2000); 
  directionalLight(40, 40, 50, 0.5, 1, -0.5);
  specularMaterial(255);

  scale(p_zoom);
  if (!isDraggingTube) orbitControl(1, 1, 0.1);

  // --- MOTEUR PHYSIQUE ---
  if (isDraggingTube) {
    handleTubeInteraction();
  } else {
    // Intégration de Verlet
    let velocity = p5.Vector.sub(p_pos, p_oldPos).mult(FRICT);
    let nextPos = p5.Vector.add(p_pos, velocity);
    nextPos.add(createVector(0, G_ENV, 0)); 

    p_oldPos = p_pos.copy();
    p_pos = nextPos;

    // CONTRAINTE 90 DEGRÉS (Le tube ne peut pas remonter plus haut que l'origine)
    if (p_pos.y < p_origin.y) {
      p_pos.y = p_origin.y;
    }

    // CONTRAINTE DE LONGUEUR DU FIL
    let dir = p5.Vector.sub(p_pos, p_origin);
    dir.setMag(p_len);
    p_pos = p5.Vector.add(p_origin, dir);

    // CONTRAINTE DU SOL (Projection propre)
    if (p_pos.y > p_floorY - P_GAP) {
        p_pos.y = p_floorY - P_GAP;
        let dx = p_pos.x - p_origin.x;
        let dz = p_pos.z - p_origin.z;
        let hLimit = sqrt(max(0, sq(p_len) - sq(p_pos.y - p_origin.y)));
        let hDir = createVector(dx, 0, dz).setMag(hLimit);
        p_pos.x = p_origin.x + hDir.x;
        p_pos.z = p_origin.z + hDir.z;
    }
  }

  // --- RENDU DÉCOR ---
  push();
  translate(0, p_floorY, 0);
  rotateX(HALF_PI);
  fill(240); 
  noStroke();
  plane(6000, 6000);
  pop();

  // --- RENDU DU TUBE ---
  renderTube();

  // --- GÉNÉRATEUR DE SABLE ---
  if (p5.Vector.dist(p_pos, p_oldPos) > 0.05 || isDraggingTube) {
    let v = p5.Vector.sub(p_pos, p_oldPos);
    for(let i = 0; i < 4; i++) {
        particles.push(new Particle(p_pos.x, p_pos.y, p_pos.z, v));
    }
  }

  // Rendu des grains
  noStroke();
  for (let i = particles.length - 1; i >= 0; i--) {
    particles[i].update();
    particles[i].display();
    if (particles.length > P_LIMIT) particles.shift();
  }
}

function handleTubeInteraction() {
  let mx = ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - width / 2) / p_zoom;
  let mz = ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - height / 2) / p_zoom;

  let target = createVector(mx, 0, mz);
  let distSq = sq(p_len) - sq(target.x - p_origin.x) - sq(target.z - p_origin.z);

  // Calcul de la hauteur sphérique
  if (distSq > 0) {
    target.y = p_origin.y + sqrt(distSq);
  } else {
    target.y = p_origin.y; // Limite à 90 degrés
  }

  // Double verrouillage des limites
  if (target.y < p_origin.y) target.y = p_origin.y;
  if (target.y > p_floorY - P_GAP) target.y = p_floorY - P_GAP;

  p_oldPos = p5.Vector.lerp(p_oldPos, p_pos, 0.05); 
  p_pos = target;
}

function renderTube() {
  push();
  translate(p_pos.x, p_pos.y, p_pos.z);

  // Orientation dynamique vers l'origine
  var v = p5.Vector.sub(p_pos, p_origin);
  let axis = createVector(0, 1, 0).cross(v);
  let angle = acos(constrain(createVector(0, 1, 0).dot(v) / v.mag(), -1, 1));
  if (axis.mag() > 0) rotate(angle, axis);

  fill(180, 0, 0);
  specularMaterial(255, 40, 40);

  // Le tube (cylindre)
  translate(0, -75, 0); 
  cylinder(22, 150); 
  pop();
}

class Particle {
  constructor(x, y, z, vTube) {
    this.pos = createVector(x, y, z);
    // Dispersion granulaire fine
    this.v = createVector(
      vTube.x * 0.4 + random(-0.4, 0.4),
      1.8, 
      vTube.z * 0.4 + random(-0.4, 0.4)
    );
    this.active = true;
    this.limit = p_floorY - random(0, 8); 
  }

  update() {
    if (this.active) {
      this.v.y += G_ENV * 0.5;
      this.pos.add(this.v);
      if (this.pos.y >= this.limit) {
        this.pos.y = this.limit;
        this.active = false;
      }
    }
  }

  display() {
    push();
    translate(this.pos.x, this.pos.y, this.pos.z);
    fill(0, 110, 240);
    box(3); // TAILLE RÉDUITE DES GRAINS
    pop();
  }
}

function mouseWheel(event) {
  p_zoom -= event.delta * 0.0008;
  p_zoom = constrain(p_zoom, 0.05, 5.0);
  return false;
}

function mousePressed() {
  let d = dist(((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - width / 2) / p_zoom, ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - height / 2) / p_zoom, p_pos.x, p_pos.z);
  if (d < 300) isDraggingTube = true;
}

function mouseReleased() {
  isDraggingTube = false;
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}

